pub fn textUniformOffset(ub_name: []const u8, u_name: []const u8) ?usize {
    if (std.mem.eql(u8, ub_name, "vs_params")) {
        if (std.mem.eql(u8, u_name, "zoom")) {
            return 0;
        }
        if (std.mem.eql(u8, u_name, "window_scale")) {
            return 64;
        }
        if (std.mem.eql(u8, u_name, "untransform")) {
            return 128;
        }
    }
    return null;
}
pub fn textUniformDesc(ub_name: []const u8, u_name: []const u8) ?sg.GlslShaderUniform {
    if (std.mem.eql(u8, ub_name, "vs_params")) {
        if (std.mem.eql(u8, u_name, "zoom")) {
            var desc: sg.GlslShaderUniform = .{};
            desc.type = .MAT4;
            desc.array_count = 0;
            desc.glsl_name = "zoom";
            return desc;
        }
        if (std.mem.eql(u8, u_name, "window_scale")) {
            var desc: sg.GlslShaderUniform = .{};
            desc.type = .MAT4;
            desc.array_count = 0;
            desc.glsl_name = "window_scale";
            return desc;
        }
        if (std.mem.eql(u8, u_name, "untransform")) {
            var desc: sg.GlslShaderUniform = .{};
            desc.type = .MAT4;
            desc.array_count = 0;
            desc.glsl_name = "untransform";
            return desc;
        }
    }
    return null;
}
